import { Directive, computed, input } from '@angular/core';
import { cn } from '@loomui-ng/ui/utils';

@Directive({
  selector: 'select[uiNativeSelect]',
  host: {
    'data-slot': 'native-select',
    '[attr.data-size]': 'size()',
    '[attr.class]': 'classes()',
  },
})
export class UiNativeSelect {
  readonly size = input<'default' | 'sm'>('default');
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('h-8 w-full min-w-0 appearance-none rounded-lg border border-input bg-transparent py-1 pe-8 ps-2.5 text-sm transition-colors outline-none select-none selection:bg-primary selection:text-primary-foreground placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:cursor-not-allowed aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-[size=sm]:h-7 data-[size=sm]:rounded-[min(var(--radius-md),10px)] data-[size=sm]:py-0.5 dark:bg-input/30 dark:hover:bg-input/50 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40', this.userClass()));
}

@Directive({
  selector: 'option[uiNativeSelectOption]',
  host: {
    'data-slot': 'native-select-option',
    '[attr.class]': 'classes()',
  },
})
export class UiNativeSelectOption {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('bg-[Canvas] text-[CanvasText]', this.userClass()));
}

@Directive({
  selector: 'optgroup[uiNativeSelectOptgroup]',
  host: {
    'data-slot': 'native-select-optgroup',
    '[attr.class]': 'classes()',
  },
})
export class UiNativeSelectOptgroup {
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn('bg-[Canvas] text-[CanvasText]', this.userClass()));
}

export const UI_NATIVE_SELECT_GENERATED = [UiNativeSelect, UiNativeSelectOption, UiNativeSelectOptgroup] as const;
